"""Inspect PDFs generated by excel-print-smoke.mjs + LibreOffice (optional PyMuPDF).

Usage: python3 scripts/check-excel-pdf.py /tmp/group-excel-print-pdf
Windows Excel's built-in PDF export should also be checked on a Windows PC.
"""
from pathlib import Path
import sys
import unicodedata
import fitz

root = Path(sys.argv[1])
files = sorted(root.glob('*.pdf'))
assert len(files) == 20, f'Expected 4 approved documents and 16 templates, found {len(files)} PDFs'
for path in files:
    doc = fitz.open(path)
    output = ''.join(page.get_text(sort=True) for page in doc)
    assert '###' not in output, f'{path.name}: numeric overflow'
    assert '\ufffd' not in output, f'{path.name}: missing character'
    for page in doc:
        assert abs(page.rect.width - 595.28) < 2 and abs(page.rect.height - 841.89) < 2, path.name
        for block in page.get_text('rawdict')['blocks']:
            for line in block.get('lines', []):
                previous = None
                for span in line['spans']:
                    for char in span['chars']:
                        value = char['c']
                        if not value.strip() or unicodedata.category(value).startswith('M'):
                            continue
                        x, y = char['origin']
                        assert 14 <= x <= page.rect.width - 14 and 14 <= y <= page.rect.height - 10, (path.name, value, x, y)
                        if previous and abs(y - previous[1]) < .5:
                            assert x - previous[0] > .2, (path.name, 'overlapping glyph origins', value, previous, (x, y))
                        previous = (x, y)
        for image in page.get_image_info():
            assert page.rect.contains(fitz.Rect(image['bbox'])), (path.name, 'clipped image')
    compact = ''.join(output.split())
    if path.stem == 'trip-report':
        assert compact.count('워크숍및학술대회참가') == 3, 'Lost trip-report paragraphs'
        assert '마지막문장:본문누락과페이지잘림없이출력검증을완료했습니다.' in compact
        assert len(doc[0].get_image_info()) == 2, 'Both signatures must print on the first page'
    elif path.stem == 'daily-log':
        assert '진행업무최종문장' in compact and '특이사항최종문장' in compact
    elif path.stem == 'expense':
        assert '900,000,000,000' in output and '900,002,100,000' in output
    print(f'PASS {path.name}: {len(doc)} A4 pages; text bounds, glyph spacing, numbers and images')
